const Q14={id:14,t:"Mean imputation of missing values",topic:"Data preprocessing",lvl:"Medium",time:"25 min",lang:"python",
desc:"Find missing values in an employee performance dataset and fill them with the column mean.",
code:String.raw`import os
import pandas as pd
import numpy as np
df = pd.read_csv("Employe_Performance_dataset.csv")
print("Count of NULL values before imputation:\n")
print(df.isnull().sum())
print("\nFirst few rows:")
print(df.head())
print("\nStatistical Summary:")
print(df.describe())
missing_col = ['Salary', 'Performance Score']
for i in missing_col:
    if df[i].isnull().sum() > 0:
        df.loc[df.loc[:, i].isnull(), i] = df.loc[:, i].mean()
print("\nCount of NULL values after imputation:\n")
print(df.isnull().sum())
print("\nUpdated DataFrame:\n")
print(df)
print("\nUpdated 'Performance Score' Column:\n")
print(df['Performance Score'].head(20))`,
fixNote:"Employe_Performance_dataset.csv is not in your document, so the Animate tab runs on a small sample dataset that I made up and labelled. Your own file will give different numbers. Also, import os and import numpy as np are never used in this program.",
steps:[["1","import os","Loads Python's os module. It is never used here, so it can be removed safely."],["2-3","import pandas / numpy","pandas reads and handles tables. numpy is imported but not used directly in this program."],["4","pd.read_csv(...)","Reads the CSV file into a DataFrame called df. The file must be in the same folder as the program."],["5-6","df.isnull().sum()","isnull() marks each missing cell True. sum() counts the True values in each column, so you see how many are missing."],["7-8","df.head()","Shows the first 5 rows so you can check the data loaded correctly."],["9-10","df.describe()","Count, mean, std, min, quartiles and max for numeric columns. A count lower than the row count reveals missing values."],["11","missing_col = [...]","A list of the two columns we want to fill."],["12","for i in missing_col:","Takes each column name in turn. i is first Salary, then Performance Score."],["13","if df[i].isnull().sum() > 0:","Only fills a column when it really has missing values."],["14","df.loc[mask, i] = mean","df.loc[:, i].isnull() is True where the value is missing. .mean() skips missing values. The mean is written only into those missing cells."],["15-16","isnull().sum() again","Should now show 0 for both columns, which proves the imputation worked."],["17-18","print(df)","Shows the full updated table."],["19-20","head(20)","The first 20 Performance Score values. Filled cells show the column mean."]],
out:"Before imputation: Salary and Performance Score show how many values are missing.\nAfter imputation: both show 0.\nThe exact numbers depend on your CSV. Open the Animate tab to watch the real output on the sample data.",
cards:[["What does df.isnull().sum() return?","The number of missing values in each column."],["What is mean imputation?","Replacing missing values with the average of the existing values in that column."],["Why use df.loc[mask, col] = value?","To change only the missing cells of one column."],["Does .mean() include missing values?","No. pandas skips NaN when computing the mean."]],
quiz:[["What does mean imputation replace missing values with?",["Zero","The column mean","The maximum","A random value"],1,"The average of the values that are present."],["Which command counts missing values per column?",["df.describe()","df.isnull().sum()","df.head()","df.mean()"],1,"isnull flags missing cells and sum counts them."]]};
