function concept(p){const c=CON[p.id];if(!c)return'';return '<div class="card concept"><h3 style="margin-top:0">Understand it first</h3><div class="cg"><div><b>What it does</b><p>'+esc(c.what)+'</p></div><div><b>Why we use it</b><p>'+esc(c.why)+'</p></div><div><b>Everyday picture</b><p>'+esc(c.pic)+'</p></div><div><b>Where it is used</b><p>'+esc(c.where)+'</p></div><div><b>Libraries</b><p>'+esc(c.libs)+'</p></div><div><b>Words to know</b><ul>'+c.words.map(w=>'<li><b>'+esc(w[0])+':</b> '+esc(w[1])+'</li>').join('')+'</ul></div></div></div>'}
